from .managed_ssh_connection_factory import ManagedSshConnectionFactory
from taf.collectors.core.factories.managed_admin_connection_factory import \
    ManagedSbtsAdminConnectionFactory
from taf.collectors.core.factories.managed_coam_cu_connection_factory import ManagedCoamCUConnectionFactory
from taf.collectors.core.factories.managed_vdu_connection_factory import ManagedVduConnectionFactory
from taf.collectors.core.entities.ssh_file_getter import SshFileGetter
from taf.collectors.core.entities.local_file_getter import LocalFileGetter
from taf.collectors.core.entities.local_executor import LocalExecutor
from taf.collectors.core.entities.ssh_executor import SshExecutor
from .named_factory import NamedComponentFactory


class CommandCollectorFactory(NamedComponentFactory):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(CommandCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments["local_executor"] = LocalExecutor()


class RemoteCommandCollectorFactory(CommandCollectorFactory):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(RemoteCommandCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        managed_ssh_connection = ManagedSshConnectionFactory().create(
            configuration=configuration["executor"],
            existing_arguments={})
        resulting_arguments["tool_executor"] = SshExecutor(
            managed_ssh_connection=managed_ssh_connection,
            sudo_password=configuration.get("sudo_password"))
        resulting_arguments["file_getter"] = SshFileGetter(
            managed_ssh_connection=managed_ssh_connection)


class LocalCommandCollectorFactory(CommandCollectorFactory):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(LocalCommandCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments["tool_executor"] = LocalExecutor(sudo_password=configuration.get("sudo_password"))
        resulting_arguments["file_getter"] = LocalFileGetter()


class CoamCUCollectorFactory(NamedComponentFactory):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(CoamCUCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        cu_connection = ManagedCoamCUConnectionFactory().create(
            configuration={"cu_connection_params": configuration["webservice"]},
            existing_arguments={})
        resulting_arguments["cu_connection"] = cu_connection


